{
  "claims": [
    {
      "claim": "基站摆放对回充的影响体现在空间要求上",
      "verdict": "unsupported",
      "evidence_index": null,
      "reason": "片段仅给出空间摆放要求，未说明该要求与回充存在因果关系"
    },
    {
      "claim": "需确保基站前方有1.5米以上、两侧有0.5米以上空间",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]明确要求基站前方1.5米以上、两侧0.5米以上空间"
    },
    {
      "claim": "空间不足可能影响主机回充",
      "verdict": "unsupported",
      "evidence_index": null,
      "reason": "片段中无任何关于空间不足影响回充的表述"
    },
    {
      "claim": "初次使用时，需将主机手动靠上基站",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]写明'开机后，请将主机手动靠上基站'"
    },
    {
      "claim": "充电极片对准充电弹片",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]写明'充电极片对准充电弹片'"
    },
    {
      "claim": "日常使用可直接短按启动智能回充",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]写明'日常使用时，可直接短按启动智能回充'"
    }
  ]
}

{
  "claims": [
    {
      "claim": "取出清水箱，检查水量是否充足；若清水箱已空，需及时添加清水至最高水位线以下",
      "verdict": "supported",
      "evidence_index": [2, 5],
      "reason": "片段[2]有“取出清水箱，加入市政自来水至最高水位线以下”；片段[5]有“请检查并补充清水箱水量”和“清水箱已空，请及时添加清水”。"
    },
    {
      "claim": "取出清水箱中的过滤管，拔出过滤管，抠开滤盖，清洗滤盖和海绵网，清理完毕后重新装回过滤管",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]原文为“取出清水箱，将清水箱中的过滤管拔出；抠开滤盖，清洗滤盖和海绵网，清理完毕后，重新装回过滤管”，内容一致。"
    },
    {
      "claim": "定期清理清水箱过滤管，避免污垢堵塞过滤管",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]原文完全一致。"
    },
    {
      "claim": "以上操作均针对清水箱",
      "verdict": "supported",
      "evidence_index": [1, 2, 5],
      "reason": "所列操作均出自片段中关于清水箱的维护、安装和故障提示。"
    },
    {
      "claim": "资料中未提及污水箱与“无法清洗拖布”故障的直接处理步骤",
      "verdict": "supported",
      "evidence_index": null,
      "reason": "检索片段中没有将污水箱操作与“无法清洗拖布”故障直接关联的处理步骤。"
    },
    {
      "claim": "拖地完成后应及时取出并清洗污水箱以避免异味、发霉",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]有“拖地完成后，请及时取出并清洗污水箱，避免产生异味、发霉”。"
    },
    {
      "claim": "资料未说明污水箱安装不到位会导致无法清洗拖布",
      "verdict": "supported",
      "evidence_index": null,
      "reason": "片段中只有“确认污水箱安装到位”等提示，未建立“安装不到位导致无法清洗拖布”的因果关系。"
    },
    {
      "claim": "故障提示中提到“请检查并清理清洗槽，并确认污水箱安装到位”与清洗功能异常相关",
      "verdict": "supported",
      "evidence_index": [5],
      "reason": "片段[5]故障排除部分包含该句，且属于清洗相关故障的处理建议。"
    },
    {
      "claim": "资料未说明水箱内部结构、密封性、水泵、阀门或电控部件的检查方法，亦未提供针对“无法清洗拖布”的其他水路排查步骤（如水管堵塞、泵故障、APP设置等）",
      "verdict": "supported",
      "evidence_index": null,
      "reason": "检索片段中未涉及这些硬件细节或额外排查步骤。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "用户型号问题为拖布不出水",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]开头写明适用问题为“RC-S200 拖布不出水排查”。"
    },
    {
      "claim": "适用资料为[1]",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "这是引用格式标注，不构成事实性论述。"
    },
    {
      "claim": "按顺序执行以下步骤，任一步骤解决后即可结束排查",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]中原文包含此说明。"
    },
    {
      "claim": "步骤1：取下水箱确认水量充足，重新安装时听到咔哒声表示到位",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "与片段[1]步骤1原文一致。"
    },
    {
      "claim": "步骤2：确认拖布支架卡入机身，拖布魔术贴平整无褶皱，出水孔未被拖布挡住",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "与片段[1]步骤2原文一致。"
    },
    {
      "claim": "步骤3：用随机附带的清理针轻轻疏通水箱出水孔，清除水垢堵塞",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "与片段[1]步骤3原文一致。"
    },
    {
      "claim": "安全提示：不要使用尖锐金属物大力捅刺出水孔",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]安全提示原文。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在的，请停止自助排查并联系官方售后",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]结尾原文。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "配网失败连不上网络时，应按以下步骤操作。",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]适用问题即“配网失败连不上网络”且给出按顺序执行步骤。"
    },
    {
      "claim": "确认手机连接 2.4GHz Wi-Fi；若为双频合一路由建议临时分开 2.4G/5G 名称。",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]步骤1原文一致。"
    },
    {
      "claim": "长按基站上的召回键与清洗键 3 秒，机器语音提示进入配网模式。",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]步骤2原文一致。"
    },
    {
      "claim": "在 App 中删除旧设备记录后重新扫描水箱盖内侧二维码绑定。",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]步骤3原文一致。"
    },
    {
      "claim": "配网失败时请优先使用 2.4GHz 网络，并将机器移至路由器附近。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]原文一致。"
    },
    {
      "claim": "进入配网模式需按说明书指定的组合键长按 3 秒，指示灯慢闪或语音提示后在 App 按引导操作。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]原文一致。"
    },
    {
      "claim": "路由器建议关闭 AP 隔离与访客网络限制，Wi-Fi 名称避免特殊符号。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]原文一致。"
    },
    {
      "claim": "双频合一路由建议临时拆分名称。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]原文一致，且片段[2]也有类似建议。"
    },
    {
      "claim": "在 App 中删除旧设备记录后重新扫码可解决大部分绑定异常。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]原文一致。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在的，请停止自助排查并联系官方售后。",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "“请联系售后”类兜底话术，不属于事实性论断。"
    }
  ]
}
